 public sealed partial class MainWindow {
  ListBox sessionSteps,sessionResults;
  void BuildDevelopmentSessions(){sessionResults=null;Text("실행 순서와 대상 폴더를 미리 확인합니다. 실행 완료는 각 프로그램의 시작 요청 기준입니다.",true);try{var p=vm.Service.ActiveProject();Text("현재 프로젝트: "+p.Name+" · "+p.Directory,true);}catch(Exception e){Text(e.Message,true);}var a=Actions();PageButton(a,"프로젝트 선택","developer-setup");sessionList=DataList("개발 세션 목록",160);sessionList.ItemsSource=vm.Service.Sessions().Presets;sessionList.ItemTemplate=(DataTemplate)System.Windows.Markup.XamlReader.Parse(@"<DataTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation'><StackPanel><TextBlock Text='{Binding}'/><TextBlock Text='{Binding Summary}' Foreground='#A1A1AA' FontSize='12'/></StackPanel></DataTemplate>");content.Children.Add(sessionList);sessionDetails=new TextBlock{TextWrapping=TextWrapping.Wrap,Foreground=Muted,Margin=new Thickness(0,0,0,12)};content.Children.Add(sessionDetails);sessionSteps=DataList("세션 실행 단계",180);content.Children.Add(sessionSteps);sessionResults=DataList("단계별 실행 요청 결과",140);sessionResults.Visibility=Visibility.Collapsed;content.Children.Add(sessionResults);sessionList.SelectionChanged+=delegate{try{var p=sessionList.SelectedItem as DevelopmentSession;sessionSteps.ItemsSource=p==null?null:p.Actions.Select((step,index)=>(index+1)+". "+step.ToString()).ToArray();sessionResults.Visibility=Visibility.Collapsed;sessionDetails.Text=p==null?"세션을 선택하세요.":vm.Service.SessionPreview(vm.Service.ActiveProject(),p);}catch(Exception e){sessionDetails.Text=e.Message;}};if(sessionList.Items.Count>0)sessionList.SelectedIndex=0;a=Actions();Action(a,"개발 세션 시작",()=>LaunchSessionFromUi(false));Action(a,"이전 개발 세션 다시 시작",()=>LaunchSessionFromUi(true));Action(a,"개발 세션 종료 기록",()=>vm.Service.EndDevelopmentSession());a=Actions();Action(a,"새 세션",()=>{Dispatcher.Invoke((Action)(()=>EditDevelopmentSession(new DevelopmentSession{Id="user-"+Guid.NewGuid().ToString("N"),Name="새 개발 세션"})));return "세션 편집을 마쳤습니다.";});Action(a,"선택 세션 편집",()=>{var selected=SelectedSession();Dispatcher.Invoke((Action)(()=>EditDevelopmentSession(vm.Service.Json.Deserialize<DevelopmentSession>(vm.Service.Json.Serialize(selected)))));return "세션 편집을 마쳤습니다.";});Action(a,"세션 복제",()=>{var copy=vm.Service.Json.Deserialize<DevelopmentSession>(vm.Service.Json.Serialize(SelectedSession()));copy.Id="user-"+Guid.NewGuid().ToString("N");copy.Name+=" 복사";copy.Builtin=false;vm.Service.SaveSession(copy);Dispatcher.Invoke((Action)(()=>Show("development-sessions")));return "세션을 복제했습니다.";});Action(a,"사용자 세션 삭제",()=>{var selected=SelectedSession();if(selected.Builtin)throw new ArgumentException("기본 세션은 삭제하지 않습니다.");bool yes=Dispatcher.Invoke(new Func<bool>(()=>Decide("개발 세션 삭제",selected.Name+"을 삭제할까요? 프로그램과 프로젝트 폴더는 유지합니다.","삭제","취소")==0));if(yes){vm.Service.DeleteSession(selected.Id);Dispatcher.Invoke((Action)(()=>Show("development-sessions")));}return yes?"사용자 세션을 삭제했습니다.":"삭제를 취소했습니다.";});var history=new TextBox{Text=String.Join("\n",vm.Service.SessionHistory().Take(10).Select(x=>x.Started+" · "+x.PresetId+" · "+x.Result+" · "+String.Join(", ",x.Actions.Select(item=>DeveloperText.Action(item.Action)+":"+item.Status))+(x.Active?" · 종료 기록 전":""))),IsReadOnly=true,Height=110,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};AutomationProperties.SetName(history,"개발 세션 실행 이력");var historySection=new Expander{Header="자세한 실행 이력",Content=history,Margin=new Thickness(0,12,0,0)};content.Children.Add(historySection);
   var elements=content.Children.Cast<UIElement>().ToArray();content.Children.Clear();var layout=new Grid();layout.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(0.4,GridUnitType.Star)});layout.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(0.6,GridUnitType.Star)});var presets=new StackPanel{Margin=new Thickness(0,0,16,0)};var inspector=new StackPanel();layout.Children.Add(presets);Grid.SetColumn(inspector,1);layout.Children.Add(inspector);content.Children.Add(layout);
   foreach(var element in elements){if(element==sessionList)presets.Children.Add(element);else if(element is WrapPanel&&((WrapPanel)element).Children.Cast<UIElement>().OfType<Button>().Any(button=>Convert.ToString(button.Content)=="새 세션"))presets.Children.Add(element);else inspector.Children.Add(element);}sessionList.Height=300;
   layout.SizeChanged+=delegate{bool compact=layout.ActualWidth<620;if(layout.RowDefinitions.Count==0){layout.RowDefinitions.Add(new RowDefinition());layout.RowDefinitions.Add(new RowDefinition());}layout.ColumnDefinitions[0].Width=new GridLength(compact?1:0.4,GridUnitType.Star);layout.ColumnDefinitions[1].Width=compact?new GridLength(0):new GridLength(0.6,GridUnitType.Star);Grid.SetColumn(inspector,compact?0:1);Grid.SetRow(inspector,compact?1:0);sessionList.Height=compact?160:300;};
  }
  DevelopmentSession SelectedSession(){return Dispatcher.Invoke(new Func<DevelopmentSession>(()=>{var s=sessionList.SelectedItem as DevelopmentSession;if(s==null)throw new ArgumentException("세션을 선택하세요.");return s;}));}
  string LaunchSessionFromUi(bool resume){ProjectEntry p;DevelopmentSession s;DeveloperPreferences prefs=null;if(resume){var last=vm.Service.ResumeConfiguration();p=last.Item1;s=last.Item2;prefs=last.Item3;}else{p=vm.Service.ActiveProject();s=SelectedSession();}string summary=vm.Service.SessionPreview(p,s,prefs);bool yes=Dispatcher.Invoke(new Func<bool>(()=>Decide("개발 세션 실행",summary,"이 구성으로 시작","취소")==0));if(!yes)return "개발 세션 시작을 취소했습니다.";bool custom=s.Actions.Any(a=>a.Enabled&&a.Kind=="command");bool consent=!custom||Dispatcher.Invoke(new Func<bool>(()=>Decide("프로젝트 명령 실행 동의",p.Name+"\n"+String.Join("\n",p.Commands??new List<string>()),"이 명령 실행 허용","명령 제외")==0));var result=vm.Service.StartSession(p,s,custom&&consent,false,prefs);string report=String.Join("\n",result.Actions.Select(x=>x.ToString()));Dispatcher.Invoke((Action)(()=>{if(sessionResults!=null){sessionResults.ItemsSource=result.Actions;sessionResults.Visibility=Visibility.Visible;}if(sessionDetails!=null)sessionDetails.Text=result.Result+" · 실행 요청 결과 (프로그램 준비 완료 여부는 별도 확인)";}));return result.Result+" · "+report;}
  void EditDevelopmentSession(DevelopmentSession session){StackPanel panel;var w=EditorWindow("개발 세션 편집",out panel);var name=EditBox(panel,"세션 이름",session.Name);var mode=Choice(panel,"실행 방식",new[]{new ChoiceOption("sequential","순차 요청"),new ChoiceOption("independent","독립 요청")},session.Mode);var terminal=Choice(panel,"세션 터미널",new[]{new ChoiceOption("","프로젝트 설정 상속"),new ChoiceOption("windows-terminal","Windows Terminal"),new ChoiceOption("cmd","CMD")},session.TerminalHost??"");var profile=Choice(panel,"세션 작업공간",new[]{new ChoiceOption("","프로젝트 설정 상속")}.Concat(vm.Service.Profiles().Select(p=>new ChoiceOption(p.Id,p.Name))),session.WorkspaceProfile??"");var allow=new CheckBox{Content="프로젝트 명령이 없을 때 이 세션의 자동 실행 허용",Foreground=TextColor,IsChecked=session.AllowAutomation};panel.Children.Add(allow);var list=DataList("세션 동작 순서",140);list.ItemsSource=session.Actions.ToArray();panel.Children.Add(list);
   var stepKind=Choice(panel,"선택 단계의 동작",new[]{"ai","project-terminal","ide","codex","opencode","wsl","cmd","powershell","terminal","folder","repository","command","tool"}.Select(x=>new ChoiceOption(x,DeveloperText.Action(x))),"");var stepEnabled=new CheckBox{Content="이 단계 실행",Foreground=TextColor};panel.Children.Add(stepEnabled);var stepTarget=Choice(panel,"등록 도구 대상",new[]{new ChoiceOption("","도구 선택")}.Concat(vm.Service.Developer().Tools.Select(t=>new ChoiceOption(t.Id,t.Name))),"");bool loadingStep=false;
   Action updateStep=()=>{if(loadingStep)return;var current=list.SelectedItem as SessionAction;if(current==null)return;current.Kind=Convert.ToString(stepKind.SelectedValue);current.Enabled=stepEnabled.IsChecked==true;if(current.Kind=="tool")current.Value=Convert.ToString(stepTarget.SelectedValue);stepTarget.IsEnabled=current.Kind=="tool";list.Items.Refresh();};
   list.SelectionChanged+=delegate{loadingStep=true;try{var current=list.SelectedItem as SessionAction;stepKind.IsEnabled=current!=null;stepEnabled.IsEnabled=current!=null;stepKind.SelectedValue=current==null?"":current.Kind;stepEnabled.IsChecked=current!=null&&current.Enabled;stepTarget.SelectedValue=current==null?"":current.Value??"";stepTarget.IsEnabled=current!=null&&current.Kind=="tool";}finally{loadingStep=false;}};stepKind.SelectionChanged+=delegate{updateStep();};stepTarget.SelectionChanged+=delegate{updateStep();};stepEnabled.Click+=delegate{updateStep();};stepKind.IsEnabled=false;stepEnabled.IsEnabled=false;stepTarget.IsEnabled=false;
   panel.Children.Add(new TextBlock{Text="대상 폴더·CLI 인수는 프로젝트 설정을 따릅니다. 등록 도구만 별도 대상을 선택합니다.",TextWrapping=TextWrapping.Wrap,Foreground=Muted});var kinds=Choice(panel,"추가할 동작",new[]{"ai","project-terminal","ide","codex","opencode","wsl","cmd","powershell","terminal","folder","repository","command"}.Select(x=>new ChoiceOption(x,DeveloperText.Action(x))),"ide");foreach(var t in vm.Service.Developer().Tools){var add=new Button{Content="도구 추가: "+t.Name};var tool=t;add.Click+=delegate{session.Actions.Add(new SessionAction{Kind="tool",Value=tool.Id});list.ItemsSource=session.Actions.ToArray();};panel.Children.Add(add);}var buttons=new WrapPanel();panel.Children.Add(buttons);var addButton=new Button{Content="동작 추가"};addButton.Click+=delegate{session.Actions.Add(new SessionAction{Kind=Convert.ToString(kinds.SelectedValue)});list.ItemsSource=session.Actions.ToArray();};buttons.Children.Add(addButton);foreach(string action in new[]{"사용 전환","위로","아래로","동작 제거"}){string operation=action;var b=new Button{Content=action};b.Click+=delegate{var selected=list.SelectedItem as SessionAction;if(selected==null)return;int index=session.Actions.IndexOf(selected);if(operation=="사용 전환")selected.Enabled=!selected.Enabled;else if(operation=="동작 제거")session.Actions.Remove(selected);else{int next=index+(operation=="위로"?-1:1);if(next>=0&&next<session.Actions.Count){session.Actions.RemoveAt(index);session.Actions.Insert(next,selected);}}list.ItemsSource=session.Actions.ToArray();list.SelectedItem=selected;};buttons.Children.Add(b);}SaveEditor(w,panel,()=>{session.Name=name.Text.Trim();session.Mode=Convert.ToString(mode.SelectedValue);session.TerminalHost=Convert.ToString(terminal.SelectedValue);session.WorkspaceProfile=Convert.ToString(profile.SelectedValue);session.AllowAutomation=allow.IsChecked==true;vm.Service.SaveSession(session);});w.ShowDialog();Show("development-sessions");}
  void BuildSmartAutomation(){Text("사용 중인 규칙만 조건이 맞을 때 실행됩니다. 세션 종료 조건은 수동 종료 기록 기준입니다.",true);ruleList=DataList("스마트 자동화 규칙",170);ruleList.ItemsSource=vm.Service.Automation().Rules;content.Children.Add(ruleList);var details=new TextBlock{Foreground=Muted,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,4,0,12)};content.Children.Add(details);ruleList.SelectionChanged+=delegate{var selected=ruleList.SelectedItem as AutomationRule;if(selected!=null)details.Text=(selected.Enabled?"사용 중":"중지됨 · 실행하지 않음")+"\n조건: "+DeveloperText.Trigger(selected.Trigger)+" · "+selected.TriggerValue+"\n추가 조건: "+(selected.Power=="any"?"전원 제한 없음":selected.Power)+"\n동작: "+DeveloperText.Action(selected.Action)+" · "+selected.Value+"\n우선순위 "+selected.Priority+" · 재실행 대기 "+selected.CooldownSeconds+"초\n최근 실행: "+DesktopService.S(vm.Service.State("automation-times"),selected.Id,"없음");};var a=Actions();Action(a,"규칙 추가",()=>{Dispatcher.Invoke((Action)(()=>EditAutomationRule(new AutomationRule{Name="새 규칙"})));return "자동화 규칙 편집을 마쳤습니다.";});Action(a,"규칙 편집",()=>{var rule=SelectedRule();var copy=vm.Service.Json.Deserialize<AutomationRule>(vm.Service.Json.Serialize(rule));Dispatcher.Invoke((Action)(()=>EditAutomationRule(copy)));return "규칙 편집을 마쳤습니다.";});Action(a,"사용 / 중지",()=>{var rule=SelectedRule();if(!rule.Enabled&&!Dispatcher.Invoke(new Func<bool>(()=>Decide("자동화 사용",rule.Name+"\n조건: "+DeveloperText.Trigger(rule.Trigger)+"\n동작: "+DeveloperText.Action(rule.Action)+"\n조건이 맞으면 사용자 조작 없이 실행됩니다.","이 규칙 사용","취소")==0)))return "규칙 사용을 취소했습니다.";rule.Enabled=!rule.Enabled;vm.Service.SaveRule(rule);Dispatcher.Invoke((Action)(()=>Show("smart-automation")));return rule.Enabled?"규칙 사용을 켰습니다.":"규칙을 중지했습니다.";});Action(a,"규칙 삭제",()=>{var rule=SelectedRule();if(Dispatcher.Invoke(new Func<bool>(()=>Decide("규칙 삭제",rule.Name+"을 삭제할까요?","삭제","취소")==0))){vm.Service.DeleteRule(rule.Id);Dispatcher.Invoke((Action)(()=>Show("smart-automation")));}return "규칙 삭제 처리를 마쳤습니다.";});var events=new TextBox{Text=vm.Service.AutomationHistory(),IsReadOnly=true,TextWrapping=TextWrapping.Wrap,Height=180,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};content.Children.Add(new Expander{Header="자동화 실행 이력",Content=events});Action(a,"실행 이력 갱신",()=>{string text=vm.Service.AutomationHistory();Dispatcher.Invoke((Action)(()=>events.Text=text));return "규칙 이력을 갱신했습니다.";});}
  AutomationRule SelectedRule(){return Dispatcher.Invoke(new Func<AutomationRule>(()=>{var rule=ruleList.SelectedItem as AutomationRule;if(rule==null)throw new ArgumentException("규칙을 선택하세요.");return rule;}));}
  void EditAutomationRule(AutomationRule rule){StackPanel panel;var w=EditorWindow("스마트 자동화 규칙 편집",out panel);var name=EditBox(panel,"규칙 이름",rule.Name);SectionHeader(panel,"언제 · 실행 조건");var trigger=Choice(panel,"조건",new[]{"session-started","session-ended","application-running","ac-connected","battery","monitor-changed"}.Select(x=>new ChoiceOption(x,DeveloperText.Trigger(x))),rule.Trigger);var triggerValue=EditBox(panel,"조건 값 (앱 이름 또는 프로젝트 ID, 세션은 비우면 모두)",rule.TriggerValue);SectionHeader(panel,"실행할 동작");var action=Choice(panel,"실행 동작",new[]{"profile","restore-owned","monitor-show","monitor-hide","wallpaper-pause","wallpaper-play","open-project","session"}.Select(x=>new ChoiceOption(x,DeveloperText.Action(x))),rule.Action);var value=EditBox(panel,"동작 대상 ID (프로필·프로젝트·세션)",rule.Value);panel.Children.Add(new TextBlock{Text="프로필: "+String.Join(", ",vm.Service.Profiles().Select(x=>x.Id))+"\n프로젝트: "+String.Join(", ",vm.Service.Projects().Select(x=>x.Id))+"\n세션: "+String.Join(", ",vm.Service.Sessions().Presets.Select(x=>x.Id)),Foreground=Muted,TextWrapping=TextWrapping.Wrap});SectionHeader(panel,"추가 조건");var power=Choice(panel,"추가 전원 조건",new[]{new ChoiceOption("any","제한 없음"),new ChoiceOption("ac","AC 연결"),new ChoiceOption("battery","배터리")},rule.Power);var exceptions=EditBox(panel,"제외할 실행 앱 이름 (쉼표 구분)",String.Join(",",rule.Exceptions));SectionHeader(panel,"고급 · 우선순위 및 재실행");var priority=EditBox(panel,"우선순위 0–100",rule.Priority.ToString());var cooldown=EditBox(panel,"재실행 대기 10–86400초",rule.CooldownSeconds.ToString());panel.Children.Add(new TextBlock{Text="저장만으로 새 규칙을 켜지 않습니다. 목록의 사용/중지에서 명시적으로 켜세요.",Foreground=Muted,TextWrapping=TextWrapping.Wrap});SaveEditor(w,panel,()=>{rule.Name=name.Text.Trim();rule.Trigger=Convert.ToString(trigger.SelectedValue);rule.TriggerValue=triggerValue.Text.Trim();rule.Action=Convert.ToString(action.SelectedValue);rule.Value=value.Text.Trim();rule.Power=Convert.ToString(power.SelectedValue);rule.Exceptions=exceptions.Text.Split(new[]{','},StringSplitOptions.RemoveEmptyEntries).Select(x=>x.Trim()).ToList();rule.Priority=Int32.Parse(priority.Text);rule.CooldownSeconds=Int32.Parse(cooldown.Text);vm.Service.SaveRule(rule);});w.ShowDialog();Show("smart-automation");}
 }
